import json
from src.nodes.base import BaseNode
from src.runtime.reality import get_reality_intelligence_engine

_EMPTY = {"reality_json": "{}", "correction_plan_json": "{}",
          "production_ready": False, "grade": "F", "score": 0.0, "exec_out": True}

class Hou_Mcp_Reality_Check(BaseNode):
    name = "hou_mcp_reality_check"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("scene_layout_json", "string", widget_type="text", default="{}")
        self.add_input("observed_scene_json", "string", widget_type="text", default="")
        self.add_output("reality_json")
        self.add_output("correction_plan_json")
        self.add_output("production_ready", "bool")
        self.add_output("grade")
        self.add_output("score", "float")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        try:
            scene = json.loads((inputs.get("scene_layout_json") or "{}").strip() or "{}")
        except Exception:
            self.log_error("scene_layout_json is not valid JSON.")
            return dict(_EMPTY)
        observed = None
        raw_obs = (inputs.get("observed_scene_json") or "").strip()
        if raw_obs:
            try:
                observed = json.loads(raw_obs)
            except Exception:
                self.log_error("observed_scene_json is not valid JSON — ignoring.")
        try:
            result = get_reality_intelligence_engine().evaluate(scene, observed)
            d = result.to_dict()
            return {
                "reality_json": json.dumps(d, sort_keys=True, indent=2),
                "correction_plan_json": json.dumps(d.get("correction_plan", {}), sort_keys=True, indent=2),
                "production_ready": result.production_ready,
                "grade": result.grade,
                "score": result.score,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Reality check failed: {exc}")
            return dict(_EMPTY)

def register_node():
    return Hou_Mcp_Reality_Check
